import java.util.*;
import java.io.*;
import java.util.stream.IntStream;
public class DivisibleByTwentyFive {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        int len = s.length();
        int end = 1;
        for (int i = 0; i < len; i++) {
            end *= 10;
        }
        long count = IntStream.range(0, end)
                .filter(i -> i % 25 == 0)
                .filter(i -> match(s, i))
                .count();
        System.out.println(count);
        sc.close();
    }
    public static boolean match(String s, int n) {
        int x = -1;
        for (int i = s.length() - 1; i >= 0; i--) {
            int d = n % 10;
            if (s.charAt(i) == 'X') {
                if (x >= 0 && x != d) {
                    return false;
                }
                x = d;
            } else if (s.charAt(i) != '_') {
                if (s.charAt(i) - '0' != d) {
                    return false;
                }
            }
            if (s.length() > 1 && i == 0 && d == 0) {
                return false;
            }
            n /= 10;
        }
        return true;
    }
}
